import { useFormContext, type FieldPath, type FieldValues } from 'react-hook-form';

import { FormControl, FormDescription, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';

export type XCardProps<TValues extends FieldValues = FieldValues> = {
  name: FieldPath<TValues>;
  label: string;
  description?: string;
};

// Render inside the shadcn <Form {...form}>. Validation lives in the form's zod schema (zodResolver), not here.
export function XCard<TValues extends FieldValues = FieldValues>({ name, label, description }: XCardProps<TValues>) {
  const { control } = useFormContext();
  return (
    <FormField
      control={control}
      name={name}
      render={({ field }) => (
        <FormItem>
          <FormLabel>{label}</FormLabel>
          <FormControl>
            {/* TODO(codegen): set type and autoComplete for this field (e.g. type="email" autoComplete="email") */}
            <Input {...field} />
          </FormControl>
          {description ? <FormDescription>{description}</FormDescription> : null}
          <FormMessage />
        </FormItem>
      )}
    />
  );
}

import { describe, expect, it } from 'vitest';
import type { ReactNode } from 'react';
import { render, screen } from '@testing-library/react';
import { useForm } from 'react-hook-form';

import { Form } from '@/components/ui/form';

import { XCard } from './x-card';

function Harness({ children }: { children: ReactNode }) {
  const form = useForm({ defaultValues: { field: '' } });
  return <Form {...form}>{children}</Form>;
}

describe('XCard', () => {
  it('labels its control', () => {
    render(
      <Harness>
        <XCard name="field" label="Label" />
      </Harness>,
    );
    expect(screen.getByLabelText('Label')).toBeTruthy();
  });

  // TODO(codegen): submit with invalid values and assert the zod error message is announced
});

